BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at) VALUES
('e1400000-0000-4000-8000-000000000001','authenticated','authenticated','quiz-admin@example.test','{}',now(),now()),
('e1400000-0000-4000-8000-000000000002','authenticated','authenticated','quiz-owner@example.test','{}',now(),now()),
('e1400000-0000-4000-8000-000000000003','authenticated','authenticated','quiz-other@example.test','{}',now(),now());
INSERT INTO public.user_roles(user_id,role,granted_by) VALUES('e1400000-0000-4000-8000-000000000001','admin','e1400000-0000-4000-8000-000000000001');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000001',true);
SELECT set_config('q.course',public.admin_create_course('assessment-security-test')::text,true);
SELECT public.admin_upsert_course_translation(current_setting('q.course')::uuid,'en','Quiz test','Test');
SELECT public.admin_set_translation_publication(current_setting('q.course')::uuid,'en',true);
SELECT public.admin_set_course_status(current_setting('q.course')::uuid,'published');
SELECT set_config('q.module',public.admin_create_course_module(current_setting('q.course')::uuid)::text,true);
SELECT public.admin_save_module_translation(current_setting('q.module')::uuid,'en','Module');
SELECT public.admin_set_module_translation_publication(current_setting('q.module')::uuid,'en',true);
SELECT set_config('q.lesson',public.admin_create_lesson(current_setting('q.module')::uuid,'assessment')::text,true);
SELECT public.admin_save_lesson_translation(current_setting('q.lesson')::uuid,'en','Quiz');
SELECT public.admin_set_lesson_translation_publication(current_setting('q.lesson')::uuid,'en',true);
SELECT public.admin_set_lesson_status(current_setting('q.lesson')::uuid,'published');
SELECT throws_ok($$SELECT public.admin_create_quiz_version(current_setting('q.lesson')::uuid,'en','Invalid','', '[{"type":"single","prompt":"Invalid","options":[{"label":"A","correct":false},{"label":"B","correct":false}]}]')$$,'23514',NULL,'missing correct key rejected atomically');
SELECT set_config('q.version',public.admin_create_quiz_version(current_setting('q.lesson')::uuid,'en','Real quiz','',
'[{"type":"single","prompt":"Single","options":[{"label":"A","correct":true},{"label":"B","correct":false}]},
{"type":"multiple","prompt":"Multiple","options":[{"label":"A","correct":true},{"label":"B","correct":true},{"label":"C","correct":false}]},
{"type":"true_false","prompt":"True or false","options":[{"label":"True","correct":true},{"label":"False","correct":false}]}]')::text,true);
SELECT throws_ok($$SELECT public.admin_localize_quiz_draft(current_setting('q.version')::uuid,'ar','اختبار','', '[{"prompt":"سؤال","options":["أ","ب"]}]')$$,'23514',NULL,'incomplete translation rejected atomically');
SELECT public.admin_localize_quiz_draft(current_setting('q.version')::uuid,'ar','اختبار','', '[{"prompt":"اختيار واحد","options":["أ","ب"]},{"prompt":"اختيارات متعددة","options":["أ","ب","ج"]},{"prompt":"صح أو خطأ","options":["صح","خطأ"]}]');
SELECT public.admin_publish_quiz_version(current_setting('q.version')::uuid);
SELECT throws_ok($$SELECT public.admin_localize_quiz_draft(current_setting('q.version')::uuid,'ar','اختبار','', '[]')$$,'23514',NULL,'published version cannot gain or change translations');
SELECT is((SELECT count(*)::int FROM public.learner_get_lesson(current_setting('q.lesson')::uuid,'en')),1,'current administrator can preview published course lessons without enrollment');
SELECT is(public.admin_preview_published_quiz(current_setting('q.lesson')::uuid,'en')->>'adminPreview','true','administrator quiz preview is explicitly read-only');
SELECT is(public.admin_preview_published_quiz(current_setting('q.lesson')::uuid,'en')->'review','null'::jsonb,'administrator preview never reveals answer keys');
SELECT ok(NOT public.admin_preview_published_quiz(current_setting('q.lesson')::uuid,'en')::text ~ 'correctOptions|explanation','administrator preview contains no answer-key fields');
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')$$,'42501',NULL,'administrator preview cannot create an attempt without enrollment');
RESET ROLE;
SELECT ok(NOT has_schema_privilege('authenticated','assessment_private','USAGE'),'keys schema private');
SELECT ok(NOT has_table_privilege('authenticated','public.question_translations','SELECT'),'explanations not directly readable');
SELECT ok(NOT has_table_privilege('authenticated','public.quiz_attempts','UPDATE'),'scores not client writable');
SELECT ok(NOT has_function_privilege('anon','public.learner_quiz_action(uuid,text,text,uuid,integer,jsonb)','EXECUTE'),'anonymous RPC execution denied');
SELECT is((SELECT count(*)::int FROM public.quiz_versions v JOIN public.quizzes q ON q.id=v.quiz_id WHERE q.lesson_id=current_setting('q.lesson')::uuid),1,'failed draft creation left no partial version');
SELECT throws_ok($$UPDATE public.quiz_versions SET pass_basis_points=0 WHERE id=current_setting('q.version')::uuid$$,'23514',NULL,'published rules immutable');
SELECT throws_ok($$UPDATE public.question_translations SET prompt='changed' WHERE question_id IN(SELECT id FROM public.questions WHERE quiz_version_id=current_setting('q.version')::uuid)$$,'23514',NULL,'published prompt immutable');
SELECT throws_ok($$DELETE FROM assessment_private.quiz_answer_keys WHERE question_id IN(SELECT id FROM public.questions WHERE quiz_version_id=current_setting('q.version')::uuid)$$,'23514',NULL,'published keys immutable');
SELECT set_config('q.answers',(SELECT jsonb_object_agg(q.id,(SELECT jsonb_agg(k.option_id) FROM assessment_private.quiz_answer_keys k WHERE k.question_id=q.id))::text FROM public.questions q WHERE q.quiz_version_id=current_setting('q.version')::uuid),true);
SELECT set_config('q.single',(SELECT id::text FROM public.questions WHERE quiz_version_id=current_setting('q.version')::uuid AND question_type='single'),true);
SELECT set_config('q.multiple',(SELECT id::text FROM public.questions WHERE quiz_version_id=current_setting('q.version')::uuid AND question_type='multiple'),true);
SELECT set_config('q.wrong',(SELECT o.id::text FROM public.question_options o JOIN public.questions q ON q.id=o.question_id WHERE q.quiz_version_id=current_setting('q.version')::uuid AND q.question_type='multiple' AND NOT EXISTS(SELECT 1 FROM assessment_private.quiz_answer_keys k WHERE k.option_id=o.id)),true);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')$$,'42501',NULL,'unenrolled learner denied');
SELECT set_config('q.enrollment',public.learner_grant_free_enrollment(current_setting('q.course')::uuid)::text,true);
SELECT set_config('q.start',public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')::text,true);
SELECT set_config('q.attempt',(current_setting('q.start')::jsonb#>>'{attempt,id}'),true);
SELECT is(current_setting('q.start')::jsonb->'review','null'::jsonb,'correctness withheld before submission');
SELECT ok(NOT (current_setting('q.start')::jsonb->'questions')::text ~ 'correct|explanation','safe question projection contains no keys');
SELECT is(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')#>>'{attempt,id}',current_setting('q.attempt'),'duplicate start resumes same attempt');
SELECT is(public.learner_evaluate_completion(current_setting('q.course')::uuid,'en')->>'completed','false','unpassed required assessment blocks course completion');
SELECT is(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,1,current_setting('q.answers')::jsonb)#>>'{attempt,sequence}','1','autosave persisted');
SELECT is(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,1,'{}')#>'{attempt,answers}',current_setting('q.answers')::jsonb,'repeated sequence cannot overwrite answers');
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,2,jsonb_build_object(current_setting('q.single'),jsonb_build_array(current_setting('q.wrong'))))$$,'22023',NULL,'cross-question option rejected');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000003',true);
SELECT public.learner_grant_free_enrollment(current_setting('q.course')::uuid);
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','get',current_setting('q.attempt')::uuid)$$,'42501',NULL,'cross-owner attempt read denied');
SELECT throws_ok($$SELECT public.admin_publish_quiz_version(current_setting('q.version')::uuid)$$,'42501',NULL,'learner cannot publish');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT set_config('q.result',public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','submit',current_setting('q.attempt')::uuid,2,current_setting('q.answers')::jsonb)::text,true);
SELECT is(current_setting('q.result')::jsonb#>>'{attempt,score}','3','all three question types score correctly');
SELECT is(current_setting('q.result')::jsonb#>>'{attempt,passed}','true','full score passes');
SELECT is(jsonb_array_length(current_setting('q.result')::jsonb->'review'),3,'answer review allowed after submission');
SELECT is(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','submit',current_setting('q.attempt')::uuid,3,'{}')#>>'{attempt,score}','3','duplicate submission keeps original result');
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,3,'{}')$$,'23514',NULL,'post-submit answers cannot change');
SELECT set_config('q.attempt',(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')#>>'{attempt,id}'),true);
SELECT is(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','submit',current_setting('q.attempt')::uuid,1,jsonb_build_object(current_setting('q.multiple'),jsonb_build_array((current_setting('q.answers')::jsonb->current_setting('q.multiple'))->>0)))#>>'{attempt,score}','0','partial multiple selection and unanswered questions receive zero');
SELECT set_config('q.attempt',(public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')#>>'{attempt,id}'),true);
SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,1,current_setting('q.answers')::jsonb);
RESET ROLE;
UPDATE public.quiz_attempts SET started_at=clock_timestamp()-interval '31 minutes',deadline=clock_timestamp()-interval '1 minute' WHERE id=current_setting('q.attempt')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT set_config('q.timeout',public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','save',current_setting('q.attempt')::uuid,2,'{}')::text,true);
SELECT is(current_setting('q.timeout')::jsonb#>>'{attempt,status}','timed_out','server deadline finalizes attempt');
SELECT is(current_setting('q.timeout')::jsonb#>>'{attempt,score}','3','late edits ignored; saved answers graded');
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'en','start')$$,'23514',NULL,'fourth attempt blocked');
SELECT throws_ok($$SELECT public.learner_quiz_action(current_setting('q.lesson')::uuid,'ar','get')$$,'42501',NULL,'unpublished locale denied');
RESET ROLE;
SELECT is((SELECT status FROM public.lesson_progress WHERE enrollment_id=current_setting('q.enrollment')::uuid AND lesson_id=current_setting('q.lesson')::uuid),'completed','passed quiz persists lesson completion');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT set_config('q.completion',(public.learner_evaluate_completion(current_setting('q.course')::uuid,'en')->>'completionId'),true);
SELECT ok(current_setting('q.completion') IS NOT NULL,'server saves completion after required quiz pass');
SELECT is(public.learner_evaluate_completion(current_setting('q.course')::uuid,'en')->>'completionId',current_setting('q.completion'),'repeated evaluation retains original snapshot');
SELECT throws_ok($$SELECT public.learner_complete_reading(current_setting('q.lesson')::uuid,'en')$$,'42501',NULL,'mark-complete cannot bypass quiz grading');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::int FROM public.course_completions),0,'other learner cannot read completion snapshot');
SELECT is(public.learner_evaluate_completion(current_setting('q.course')::uuid,'en')->>'completed','false','other learner cannot inherit pass');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000001',true);
SELECT set_config('q.reading',public.admin_create_lesson(current_setting('q.module')::uuid,'article',false)::text,true);
SELECT public.admin_save_lesson_translation(current_setting('q.reading')::uuid,'en','Reading');
SELECT public.admin_set_lesson_translation_publication(current_setting('q.reading')::uuid,'en',true);
SELECT public.admin_set_lesson_status(current_setting('q.reading')::uuid,'published');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.learner_complete_reading(current_setting('q.reading')::uuid,'en')$$,'23514',NULL,'empty article cannot be marked complete');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000001',true);
SELECT public.admin_save_lesson_translation(current_setting('q.reading')::uuid,'en','Reading',null,'Actual test article');
SELECT public.admin_set_lesson_translation_publication(current_setting('q.reading')::uuid,'en',true);
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT lives_ok($$SELECT public.learner_complete_reading(current_setting('q.reading')::uuid,'en')$$,'available article supports explicit completion');
SELECT is(public.learner_evaluate_completion(current_setting('q.course')::uuid,'en')->>'completionId',current_setting('q.completion'),'later curriculum changes preserve historical completion');
RESET ROLE;
SELECT throws_ok($$UPDATE public.course_completions SET required_lessons=99 WHERE id=current_setting('q.completion')::uuid$$,'23514',NULL,'historical completion is immutable');
SELECT ok(NOT has_table_privilege('authenticated','public.course_completions','INSERT'),'learner cannot forge completion');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT public.learner_issue_certificate(current_setting('q.completion')::uuid,'en')$$,'42501',NULL,'cross-owner certificate issuance denied');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT set_config('q.certificate',public.learner_issue_certificate(current_setting('q.completion')::uuid,'en')::text,true);
SELECT is(public.learner_issue_certificate(current_setting('q.completion')::uuid,'ar')::text,current_setting('q.certificate'),'one certificate identity per completion, both presentation locales');
SELECT set_config('q.token',(SELECT verification_token::text FROM public.learner_list_certificates() LIMIT 1),true);
SELECT is((SELECT count(*)::int FROM public.learner_list_certificates()),1,'owner can list certificate');
SELECT is(public.learner_learning_summary('en')->>'completedCourses','1','dashboard completion count uses snapshot');
SELECT is(public.learner_learning_summary('en')->>'certificates','1','dashboard certificate count uses issued records');
SELECT throws_ok($$SELECT public.admin_revoke_certificate(current_setting('q.certificate')::uuid)$$,'42501',NULL,'learner cannot revoke certificates');
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::int FROM public.learner_list_certificates()),0,'other learner cannot list owner certificate');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT is((SELECT status FROM public.verify_certificate(current_setting('q.token')::uuid)),'valid','opaque public verification works without login');
SELECT is((SELECT count(*)::int FROM public.verify_certificate(gen_random_uuid())),0,'invalid verification token reveals no record');
SELECT ok(NOT (SELECT to_jsonb(v) FROM public.verify_certificate(current_setting('q.token')::uuid) v) ? 'user_id','public verification excludes internal learner identifiers');
RESET ROLE;
SELECT ok(NOT has_table_privilege('authenticated','public.certificates','INSERT'),'certificate cannot be fabricated by direct write');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000001',true);
SELECT lives_ok($$SELECT public.admin_revoke_certificate(current_setting('q.certificate')::uuid)$$,'current administrator can revoke');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.admin_audit_log WHERE certificate_id=current_setting('q.certificate')::uuid AND action='certificate.revoked'),1,'revocation has a typed audit record');
SET LOCAL ROLE anon;
SELECT is((SELECT status FROM public.verify_certificate(current_setting('q.token')::uuid)),'revoked','verification reflects revocation');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1400000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.learner_issue_certificate(current_setting('q.completion')::uuid,'en')$$,'23514',NULL,'learner cannot reverse a revocation');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
